/**
 * 이 Worker 하나가 세 가지 역할을 합니다:
 * 1. /api/assets  → 차량 데이터 저장/조회 (Cloudflare KV)
 * 2. /api/ai      → Anthropic API 중계 (API 키는 여기(서버)에만 보관)
 * 3. 그 외 모든 요청 → 아래에 내장된 HTML(index.html 내용) 그대로 응답
 *
 * (정적 자산 바인딩(env.ASSETS)을 쓰지 않고 HTML을 코드에 직접 내장해서,
 *  자산 바인딩 설정 문제로 인한 오류를 원천적으로 피합니다.)
 */

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, x-app-token",
};

const KV_KEY = "assets-data";

const HTML_CONTENT = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>\uc790\uc0b0\ud0dd \u2014 \uc7a5\ube44 \uad00\ub9ac</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+KR:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<style>\n  :root{\n    --bg:#14171C; --surface:#1C2027; --surface-2:#242933; --line:#2E3440;\n    --text:#E8EAEE; --muted:#8B93A0;\n    --accent:#FF8A3D; --accent-dim:#3A2A1C;\n    --ok:#3DDC97; --ok-dim:#1B2E27;\n    --warn:#F0C020; --warn-dim:#332C14;\n    --danger:#FF5D5D; --danger-dim:#331A1A;\n    --radius:10px;\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{background:var(--bg); color:var(--text); font-family:'IBM Plex Sans KR', -apple-system, sans-serif; min-height:100vh; -webkit-tap-highlight-color:transparent;}\n  .mono{font-family:'IBM Plex Mono', monospace;}\n  header{position:sticky; top:0; z-index:20; background:linear-gradient(180deg, #14171C 85%, transparent); padding:16px 16px 8px; border-bottom:1px solid var(--line);}\n  .brand{display:flex; align-items:center; gap:10px;}\n  .brand .tag{width:34px;height:34px;border-radius:8px; background:repeating-linear-gradient(90deg, var(--accent) 0 3px, transparent 3px 6px, var(--accent) 6px 8px, transparent 8px 11px); flex:0 0 auto;}\n  .brand h1{font-size:18px; margin:0; letter-spacing:.2px;}\n  .brand p{margin:1px 0 0; font-size:12px; color:var(--muted);}\n  nav{display:flex; gap:6px; margin-top:14px; overflow-x:auto; padding-bottom:2px;}\n  nav button{flex:0 0 auto; background:transparent; border:1px solid var(--line); color:var(--muted); padding:8px 13px; border-radius:999px; font-size:12.5px; font-weight:500; cursor:pointer; transition:.15s; white-space:nowrap;}\n  nav button.active{background:var(--accent); border-color:var(--accent); color:#1a1200;}\n  main{padding:16px; max-width:640px; margin:0 auto; padding-bottom:80px;}\n  .view{display:none;}\n  .view.active{display:block;}\n  .card{background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:16px; margin-bottom:12px;}\n  .card h2{font-size:14px; margin:0 0 10px; color:var(--muted); font-weight:600; text-transform:uppercase; letter-spacing:.06em;}\n  button.primary{background:var(--accent); color:#1a1200; border:none; border-radius:8px; padding:12px 16px; font-weight:600; font-size:14px; cursor:pointer; width:100%;}\n  button.secondary{background:transparent; color:var(--text); border:1px solid var(--line); border-radius:8px; padding:11px 16px; font-weight:500; font-size:14px; cursor:pointer; width:100%;}\n  button.small{background:var(--surface-2); color:var(--text); border:1px solid var(--line); border-radius:6px; padding:6px 10px; font-size:12px; cursor:pointer;}\n  button:disabled{opacity:.5; cursor:not-allowed;}\n  button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible{outline:2px solid var(--accent); outline-offset:2px;}\n  input, textarea, select{width:100%; background:var(--surface-2); border:1px solid var(--line); color:var(--text); border-radius:8px; padding:10px 12px; font-size:14px; font-family:inherit; margin-top:4px;}\n  label{font-size:12px; color:var(--muted); display:block; margin-top:10px;}\n  .row{display:flex; gap:8px;}\n  .row > *{flex:1;}\n  .badge{display:inline-block; padding:2px 9px; border-radius:999px; font-size:11px; font-weight:600;}\n  .badge.ok{background:var(--ok-dim); color:var(--ok);}\n  .badge.warn{background:var(--warn-dim); color:var(--warn);}\n  .badge.danger{background:var(--danger-dim); color:var(--danger);}\n  .badge.muted{background:var(--surface-2); color:var(--muted);}\n  .asset-item{display:flex; gap:12px; padding:12px; border:1px solid var(--line); border-radius:8px; margin-bottom:8px; background:var(--surface-2); cursor:pointer;}\n  .asset-item .strip{width:5px; border-radius:3px; background:repeating-linear-gradient(180deg, var(--accent) 0 4px, transparent 4px 7px);}\n  .asset-item .body{flex:1; min-width:0;}\n  .asset-item .top{display:flex; justify-content:space-between; align-items:baseline; gap:8px;}\n  .asset-item .name{font-weight:600; font-size:14px;}\n  .asset-item .meta{font-size:12px; color:var(--muted); margin-top:3px;}\n  .asset-item .code{font-size:11px; color:var(--muted); margin-top:4px;}\n  .empty{text-align:center; padding:36px 16px; color:var(--muted);}\n  .empty .big{font-size:32px; margin-bottom:8px;}\n  .stat-grid{display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:12px;}\n  .stat{background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:14px;}\n  .stat .num{font-size:26px; font-weight:700; font-family:'IBM Plex Mono';}\n  .stat .lbl{font-size:12px; color:var(--muted); margin-top:2px;}\n  .bar-row{display:flex; align-items:center; gap:8px; margin:8px 0; font-size:13px;}\n  .bar-row .lbl{width:76px; flex:0 0 auto; color:var(--muted); font-size:12px;}\n  .bar-track{flex:1; height:10px; background:var(--surface-2); border-radius:5px; overflow:hidden;}\n  .bar-fill{height:100%; background:var(--accent); border-radius:5px;}\n  .bar-row .cnt{width:26px; text-align:right; font-family:'IBM Plex Mono'; font-size:12px; color:var(--muted);}\n  .chat-log{display:flex; flex-direction:column; gap:10px; margin-bottom:12px; min-height:80px;}\n  .msg{padding:10px 12px; border-radius:10px; font-size:14px; line-height:1.5; max-width:92%;}\n  .msg.user{align-self:flex-end; background:var(--accent-dim); border:1px solid #4a3320;}\n  .msg.ai{align-self:flex-start; background:var(--surface-2); border:1px solid var(--line); white-space:pre-wrap;}\n  .chip-row{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px;}\n  .chip{background:var(--surface-2); border:1px solid var(--line); color:var(--muted); padding:6px 10px; border-radius:999px; font-size:12px; cursor:pointer;}\n  .chip.active{background:var(--accent); color:#1a1200; border-color:var(--accent);}\n  .match-card{background:var(--surface); border:1px solid var(--line); border-radius:8px; padding:10px; margin-top:6px;}\n  .match-card .diff{font-size:13px; margin:4px 0;}\n  .match-card .diff .from{color:var(--danger); text-decoration:line-through;}\n  .match-card .diff .to{color:var(--ok); font-weight:600;}\n  .match-actions{display:flex; gap:6px; margin-top:8px;}\n  .match-actions button{flex:1;}\n  .modal-bg{position:fixed; inset:0; background:rgba(0,0,0,.6); z-index:50; display:none; align-items:flex-end; justify-content:center;}\n  .modal-bg.active{display:flex;}\n  .modal{background:var(--surface); border:1px solid var(--line); border-radius:16px 16px 0 0; width:100%; max-width:640px; padding:18px; max-height:88vh; overflow-y:auto;}\n  .modal h3{margin:0 0 4px; font-size:16px;}\n  .modal .sub{font-size:12px; color:var(--muted); margin-bottom:6px; font-family:'IBM Plex Mono';}\n  .close-x{float:right; background:none; border:none; color:var(--muted); font-size:20px; cursor:pointer; line-height:1;}\n  .toast{position:fixed; bottom:20px; left:50%; transform:translateX(-50%); background:var(--surface-2); border:1px solid var(--line); color:var(--text); padding:10px 16px; border-radius:8px; font-size:13px; z-index:60; opacity:0; transition:opacity .25s; pointer-events:none; max-width:88%; text-align:center;}\n  .toast.show{opacity:1;}\n  .spin{width:16px; height:16px; border:2px solid var(--muted); border-top-color:var(--accent); border-radius:50%; display:inline-block; animation:spin .7s linear infinite; vertical-align:-3px;}\n  @keyframes spin{to{transform:rotate(360deg)}}\n  .hint{font-size:12px; color:var(--muted); margin-top:8px; line-height:1.5;}\n  table.preview{width:100%; border-collapse:collapse; font-size:12px; margin-top:10px;}\n  table.preview th, table.preview td{border:1px solid var(--line); padding:6px 8px; text-align:left; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:120px;}\n  table.preview th{background:var(--surface-2); color:var(--muted); font-weight:500;}\n  .table-scroll{overflow-x:auto;}\n  .history-item{font-size:12px; color:var(--muted); padding:6px 0; border-bottom:1px solid var(--line);}\n  .history-item b{color:var(--text);}\n  .drop-zone{border:2px dashed var(--line); border-radius:10px; padding:24px 16px; text-align:center; color:var(--muted); font-size:13px; cursor:pointer;}\n  .drop-zone.drag{border-color:var(--accent); color:var(--accent);}\n  .group-header{display:flex; align-items:center; gap:8px; margin:16px 0 8px; color:var(--muted); font-size:12px; font-weight:600; text-transform:uppercase; letter-spacing:.05em;}\n  .group-header:first-child{margin-top:0;}\n  .group-header .line{flex:1; height:1px; background:var(--line);}\n  .group-header .cnt{background:var(--surface-2); padding:2px 8px; border-radius:999px; font-family:'IBM Plex Mono'; text-transform:none; letter-spacing:0;}\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"brand\">\n    <div class=\"tag\"></div>\n    <div><h1>\uc790\uc0b0\ud0dd</h1><p>\ud68c\uc0ac \ube44\ud488 \u00b7 \ucc28\ub7c9 \u00b7 \uc7a5\ube44 \uad00\ub9ac</p></div>\n  </div>\n  <nav>\n    <button data-view=\"assets\" class=\"active\">\uc790\uc0b0 \ubaa9\ub85d</button>\n    <button data-view=\"bulk\">\uc5d1\uc140 \uc77c\uad04\ub4f1\ub85d</button>\n    <button data-view=\"ai\">AI \uba85\ub839</button>\n    <button data-view=\"dash\">\ub300\uc2dc\ubcf4\ub4dc</button>\n  </nav>\n</header>\n\n<main>\n\n  <!-- ASSETS -->\n  <div class=\"view active\" id=\"view-assets\">\n    <div class=\"card\">\n      <input type=\"text\" id=\"search-input\" placeholder=\"\uc774\ub984, \ubc14\ucf54\ub4dc/\ucc28\ub7c9\ubc88\ud638, \uc704\uce58, \ub2f4\ub2f9\uc790\ub85c \uac80\uc0c9\">\n      <label style=\"margin-top:12px;\">\uce74\ud14c\uace0\ub9ac</label>\n      <div class=\"chip-row\" id=\"category-filters\" style=\"margin-top:6px;\"></div>\n      <label style=\"margin-top:4px;\">\ubcf4\uad00 \uc704\uce58</label>\n      <div class=\"chip-row\" id=\"location-filters\" style=\"margin-top:6px;\"></div>\n      <label class=\"toggle-row\" style=\"display:flex; align-items:center; gap:8px; margin-top:10px; color:var(--text); font-size:13px;\">\n        <input type=\"checkbox\" id=\"chk-group-location\" style=\"width:auto; margin:0;\"> \uc704\uce58\ubcc4\ub85c \ubb36\uc5b4\uc11c \ubcf4\uae30\n      </label>\n      <button class=\"secondary\" id=\"btn-add-manual\" style=\"margin-top:12px;\">+ \uc790\uc0b0 \uc9c1\uc811 \ub4f1\ub85d</button>\n    </div>\n    <div id=\"asset-list\"></div>\n  </div>\n\n  <!-- BULK IMPORT -->\n  <div class=\"view\" id=\"view-bulk\">\n    <div class=\"card\">\n      <h2>\uc5d1\uc140/CSV\ub85c \uc77c\uad04 \ub4f1\ub85d</h2>\n      <p class=\"hint\" style=\"margin-top:0;\">\ucc28\ub7c9 300\ub300\ucc98\ub7fc \ub9ce\uc740 \uc790\uc0b0\uc744 \ud55c \ubc88\uc5d0 \ub4f1\ub85d\ud560 \ub54c \uc0ac\uc6a9\ud558\uc138\uc694. \uccab \ubc88\uc9f8 \ud589\uc740 \uc81c\ubaa9(\ud5e4\ub354)\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4.</p>\n      <div class=\"drop-zone\" id=\"drop-zone\">\n        \ud83d\udcc4 \ud30c\uc77c\uc744 \uc120\ud0dd\ud558\uac70\ub098 \uc5ec\uae30\ub85c \ub04c\uc5b4\ub2e4 \ub193\uc73c\uc138\uc694<br><span style=\"font-size:11px;\">.xlsx / .xls / .csv</span>\n        <input type=\"file\" id=\"file-input\" accept=\".xlsx,.xls,.csv\" style=\"display:none;\">\n      </div>\n    </div>\n    <div id=\"bulk-mapping\"></div>\n  </div>\n\n  <!-- AI COMMAND -->\n  <div class=\"view\" id=\"view-ai\">\n    <div class=\"card\">\n      <h2>AI\uc5d0\uac8c \ubb3c\uc5b4\ubcf4\uac70\ub098 \uba85\ub839\ud558\uae30</h2>\n      <div class=\"chip-row\">\n        <div class=\"chip\" data-prompt=\"\uc810\uac80\uc774 \ud544\uc694\ud558\uac70\ub098 \uc624\ub798 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc790\uc0b0\uc744 \uc694\uc57d\ud574\uc918\">\uc810\uac80 \ud544\uc694 \uc694\uc57d</div>\n        <div class=\"chip\" data-prompt=\"\uce74\ud14c\uace0\ub9ac\ubcc4\ub85c \uc790\uc0b0 \ud604\ud669\uc744 \ubd84\uc11d\ud574\uc918\">\uce74\ud14c\uace0\ub9ac \ubd84\uc11d</div>\n        <div class=\"chip\" data-prompt=\"\ubd84\uc2e4 \ub610\ub294 \uc0c1\ud0dc\uac00 \uc774\uc0c1\ud55c \uc790\uc0b0\uc774 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc918\">\uc774\uc0c1 \uc9d5\ud6c4 \ud655\uc778</div>\n      </div>\n      <div class=\"chat-log\" id=\"chat-log\"></div>\n      <div class=\"row\">\n        <input type=\"text\" id=\"chat-input\" placeholder='\uc608: \"12\uac003456 \uc0ac\uc6a9\uc790\ub97c \uae40\ucca0\uc218\ub85c \ubc14\uafd4\uc918\"'>\n        <button class=\"secondary\" style=\"flex:0 0 70px;\" id=\"btn-chat-send\">\uc804\uc1a1</button>\n      </div>\n      <p class=\"hint\">\uc9c8\ubb38(\"\uc5b4\ub514 \uc788\uc9c0?\")\uacfc \ubcc0\uacbd \uba85\ub839(\"\uc0ac\uc6a9\uc790\ub97c ~\ub85c \ubc14\uafd4\uc918\") \ub458 \ub2e4 \uac00\ub2a5\ud569\ub2c8\ub2e4. \ubcc0\uacbd \uba85\ub839\uc740 \ubc18\ub4dc\uc2dc \ud655\uc778 \ud6c4 \uc801\uc6a9\ub429\ub2c8\ub2e4.</p>\n    </div>\n  </div>\n\n  <!-- DASHBOARD -->\n  <div class=\"view\" id=\"view-dash\">\n    <div class=\"stat-grid\" id=\"stat-grid\"></div>\n    <div class=\"card\"><h2>\uce74\ud14c\uace0\ub9ac\ubcc4 \ubd84\ud3ec</h2><div id=\"category-bars\"></div></div>\n    <div class=\"card\"><h2>\ubcf4\uad00 \uc704\uce58\ubcc4 \ubd84\ud3ec</h2><div id=\"location-bars\"></div></div>\n    <div class=\"card\"><h2>\uc0c1\ud0dc\ubcc4 \ud604\ud669</h2><div id=\"status-bars\"></div></div>\n    <div class=\"card\">\n      <button class=\"primary\" id=\"btn-export-excel\">\ud83d\udce5 \ud604\uc7ac \uc790\uc0b0 \ub370\uc774\ud130 \uc5d1\uc140\ub85c \ub2e4\uc6b4\ub85c\ub4dc</button>\n      <p class=\"hint\">\ub4f1\ub85d\ub41c \ubaa8\ub4e0 \uc790\uc0b0(\ucc28\ub7c9 \ud3ec\ud568)\uc744 \uc5d1\uc140 \ud30c\uc77c\ub85c \uc800\uc7a5\ud569\ub2c8\ub2e4. \ubc31\uc5c5\uc6a9\uc774\ub098 \ubcf4\uace0\uc6a9\uc73c\ub85c \ud65c\uc6a9\ud558\uc138\uc694.</p>\n    </div>\n    <div class=\"card\">\n      <button class=\"secondary\" id=\"btn-ai-report\">AI \uc774\uc0c1 \uc9d5\ud6c4 \ubd84\uc11d \uc2e4\ud589</button>\n      <div id=\"ai-report\" style=\"margin-top:10px;\"></div>\n    </div>\n    <div class=\"card\">\n      <button class=\"secondary\" id=\"btn-reset\" style=\"border-color:#4a2020; color:var(--danger);\">\uc804\uccb4 \ub370\uc774\ud130 \ucd08\uae30\ud654</button>\n    </div>\n  </div>\n\n</main>\n\n<!-- ADD/EDIT MODAL -->\n<div class=\"modal-bg\" id=\"modal-bg\">\n  <div class=\"modal\">\n    <button class=\"close-x\" id=\"modal-close\">&times;</button>\n    <h3 id=\"modal-title\">\uc790\uc0b0 \ub4f1\ub85d</h3>\n    <div class=\"sub mono\" id=\"modal-barcode\"></div>\n\n    <label>\uc790\uc0b0\uba85</label>\n    <div class=\"row\">\n      <input type=\"text\" id=\"f-name\" placeholder=\"\uc608: \uadf8\ub79c\uc800 IG (\ucc28\ub7c9) / \uc0bc\uc131 \ubaa8\ub2c8\ud130 27\uc778\uce58\">\n      <button class=\"small\" id=\"btn-ai-classify\" style=\"flex:0 0 110px;\">\u2728 AI \uc790\ub3d9\ubd84\ub958</button>\n    </div>\n\n    <label>\uce74\ud14c\uace0\ub9ac (\ucc28\uc885 \ucf54\ub4dc \ub4f1 \uc790\uc720 \uc785\ub825)</label>\n    <input type=\"text\" id=\"f-category\" list=\"dl-category\" placeholder=\"\uc608: LMC, LPU, \ubc84\uc2a4, \uc0ac\ubb34\uae30\uae30 \ub4f1\">\n    <datalist id=\"dl-category\"></datalist>\n\n    <label>\ubcf4\uad00 \uc704\uce58</label>\n    <input type=\"text\" id=\"f-location\" placeholder=\"\uc608: \ubcf8\uc0ac \uc9c0\ud558\uc8fc\ucc28\uc7a5 / 3\uce35 \uc0ac\ubb34\uc2e4\">\n    <label>\ub2f4\ub2f9\uc790 / \uc0ac\uc6a9\uc790</label>\n    <input type=\"text\" id=\"f-assignee\" placeholder=\"\uc608: \ud64d\uae38\ub3d9\">\n    <label>\uc0c1\ud0dc</label>\n    <select id=\"f-status\">\n      <option value=\"ok\">\uc815\uc0c1</option><option value=\"check\">\uc810\uac80 \ud544\uc694</option>\n      <option value=\"lost\">\ubd84\uc2e4</option><option value=\"retired\">\ud3d0\uae30</option>\n    </select>\n    <label>\uba54\ubaa8</label>\n    <textarea id=\"f-notes\" rows=\"2\" placeholder=\"\ucd94\uac00 \uc815\ubcf4\"></textarea>\n\n    <button class=\"primary\" id=\"btn-save-asset\" style=\"margin-top:16px;\">\uc800\uc7a5</button>\n    <button class=\"secondary\" id=\"btn-delete-asset\" style=\"margin-top:8px; display:none; border-color:#4a2020; color:var(--danger);\">\uc774 \uc790\uc0b0 \uc0ad\uc81c</button>\n\n    <div id=\"history-section\" style=\"margin-top:16px; display:none;\">\n      <label style=\"margin-top:0;\">\ubcc0\uacbd \uc774\ub825</label>\n      <div id=\"history-list\"></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n/* =========================================================================\n   \uc811\uc18d \ucf54\ub4dc \uac8c\uc774\ud2b8 + API \ud638\ucd9c \ub3c4\uc6b0\ubbf8\n   \uc774 \uc0ac\uc774\ud2b8\uc758 \ubc31\uc5d4\ub4dc(/api/assets, /api/ai)\ub294 Cloudflare Pages Functions\uc785\ub2c8\ub2e4.\n   \uac19\uc740 \ub3c4\uba54\uc778(origin)\uc5d0\uc11c \ud638\ucd9c\ud558\ubbc0\ub85c \ubcc4\ub3c4 URL \uc124\uc815\uc774 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.\n   \ub300\uc2e0 Cloudflare \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \uc124\uc815\ud55c \"\uc811\uc18d \ucf54\ub4dc(APP_ACCESS_TOKEN)\"\ub97c\n   \ubaa8\ub4e0 \uc694\uccad\uc5d0 \ud568\uaed8 \ubcf4\ub0b4\uc57c \uc11c\ubc84\uac00 \uc694\uccad\uc744 \ud5c8\uc6a9\ud569\ub2c8\ub2e4.\n   ========================================================================= */\nfunction getAppToken(){\n  let token = localStorage.getItem('app_token');\n  if(!token){\n    token = prompt('\uc811\uc18d \ucf54\ub4dc\ub97c \uc785\ub825\ud558\uc138\uc694 (\uad00\ub9ac\uc790\uc5d0\uac8c \ubb38\uc758):');\n    if(token) localStorage.setItem('app_token', token.trim());\n  }\n  return (token || '').trim();\n}\n\nasync function apiFetch(path, options={}){\n  const headers = Object.assign({}, options.headers, {'x-app-token': getAppToken()});\n  const res = await fetch(path, Object.assign({}, options, {headers}));\n  if(res.status === 401){\n    localStorage.removeItem('app_token');\n    throw new Error('\uc811\uc18d \ucf54\ub4dc\uac00 \uc62c\ubc14\ub974\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc0c8\ub85c\uace0\uce68 \ud6c4 \ub2e4\uc2dc \uc785\ub825\ud574\uc8fc\uc138\uc694.');\n  }\n  return res;\n}\n</script>\n\n<script>\n/* ---------------- storage (Cloudflare KV via /api/assets) ---------------- */\nlet assets = {};\nlet editingBarcode = null;\n\nfunction toast(msg){\n  const t = document.getElementById('toast');\n  t.textContent = msg;\n  t.classList.add('show');\n  clearTimeout(window._toastT);\n  window._toastT = setTimeout(()=>t.classList.remove('show'), 2600);\n}\n\nasync function loadAssets(){\n  try{\n    const res = await apiFetch('/api/assets');\n    if(!res.ok) throw new Error('\uc11c\ubc84 \uc624\ub958 (' + res.status + ')');\n    assets = await res.json();\n  }catch(e){\n    toast('\ubd88\ub7ec\uc624\uae30 \uc624\ub958: ' + e.message);\n    assets = {};\n  }\n}\nasync function saveAssets(){\n  try{\n    const res = await apiFetch('/api/assets', {\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body: JSON.stringify(assets)\n    });\n    if(!res.ok) throw new Error('\uc11c\ubc84 \uc624\ub958 (' + res.status + ')');\n  }catch(e){ toast('\uc800\uc7a5 \uc624\ub958: ' + e.message); }\n}\n\nfunction daysSince(iso){ if(!iso) return null; return Math.floor((Date.now() - new Date(iso).getTime()) / 86400000); }\nfunction checkBadge(d){\n  if(d === null) return '<span class=\"badge muted\">\ubbf8\ud655\uc778</span>';\n  if(d <= 30) return `<span class=\"badge ok\">${d}\uc77c \uc804 \ud655\uc778</span>`;\n  if(d <= 90) return `<span class=\"badge warn\">${d}\uc77c \uc804 \ud655\uc778</span>`;\n  return `<span class=\"badge danger\">${d}\uc77c \uc804 \ud655\uc778 \u00b7 \uc810\uac80\ud544\uc694</span>`;\n}\nfunction statusBadge(s){\n  const map = {ok:['\uc815\uc0c1','ok'], check:['\uc810\uac80 \ud544\uc694','warn'], lost:['\ubd84\uc2e4','danger'], retired:['\ud3d0\uae30','muted']};\n  const [label, cls] = map[s] || ['\uc815\uc0c1','ok'];\n  return `<span class=\"badge ${cls}\">${label}</span>`;\n}\nfunction escapeHtml(s){\n  return String(s ?? '').replace(/[&<>\"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n}\nfunction addHistory(barcode, field, from, to, via){\n  if(!assets[barcode]) return;\n  if(!assets[barcode].history) assets[barcode].history = [];\n  assets[barcode].history.unshift({date:new Date().toISOString(), field, from: from||'(\uc5c6\uc74c)', to, via});\n  if(assets[barcode].history.length > 30) assets[barcode].history.length = 30;\n}\nconst FIELD_LABEL = {name:'\uc790\uc0b0\uba85', category:'\uce74\ud14c\uace0\ub9ac', location:'\uc704\uce58', assignee:'\ub2f4\ub2f9\uc790', status:'\uc0c1\ud0dc', notes:'\uba54\ubaa8'};\n\n/* ---------------- nav ---------------- */\ndocument.querySelectorAll('nav button').forEach(btn=>{\n  btn.addEventListener('click', ()=>{\n    document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));\n    btn.classList.add('active');\n    document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));\n    document.getElementById('view-'+btn.dataset.view).classList.add('active');\n    if(btn.dataset.view === 'assets') renderAssetList();\n    if(btn.dataset.view === 'dash') renderDashboard();\n  });\n});\n\n/* ---------------- modal ---------------- */\nconst modalBg = document.getElementById('modal-bg');\nfunction openModal(barcode, isNew){\n  editingBarcode = barcode;\n  const rec = assets[barcode] || {};\n  document.getElementById('modal-title').textContent = isNew || !assets[barcode] ? '\uc790\uc0b0 \ub4f1\ub85d' : '\uc790\uc0b0 \uc815\ubcf4 \uc218\uc815';\n  document.getElementById('modal-barcode').textContent = barcode;\n  document.getElementById('f-name').value = rec.name || '';\n  document.getElementById('f-category').value = rec.category || '';\n  document.getElementById('f-location').value = rec.location || '';\n  document.getElementById('f-assignee').value = rec.assignee || '';\n  document.getElementById('f-status').value = rec.status || 'ok';\n  document.getElementById('f-notes').value = rec.notes || '';\n  document.getElementById('btn-delete-asset').style.display = assets[barcode] ? 'block' : 'none';\n  const histSec = document.getElementById('history-section');\n  if(rec.history && rec.history.length){\n    histSec.style.display = 'block';\n    document.getElementById('history-list').innerHTML = rec.history.slice(0,10).map(h=>\n      `<div class=\"history-item\">${new Date(h.date).toLocaleString('ko-KR')} \u00b7 <b>${FIELD_LABEL[h.field]||h.field}</b>: ${escapeHtml(h.from)} \u2192 <b>${escapeHtml(h.to)}</b> ${h.via==='ai'?'(AI \uba85\ub839)':''}</div>`\n    ).join('');\n  }else{ histSec.style.display = 'none'; }\n  modalBg.classList.add('active');\n}\ndocument.getElementById('modal-close').addEventListener('click', ()=> modalBg.classList.remove('active'));\nmodalBg.addEventListener('click', e=>{ if(e.target === modalBg) modalBg.classList.remove('active'); });\ndocument.getElementById('btn-add-manual').addEventListener('click', ()=>{\n  openModal('MANUAL-' + Date.now().toString().slice(-8), true);\n});\ndocument.getElementById('btn-save-asset').addEventListener('click', async ()=>{\n  const name = document.getElementById('f-name').value.trim();\n  if(!name){ toast('\uc790\uc0b0\uba85\uc744 \uc785\ub825\ud574\uc8fc\uc138\uc694.'); return; }\n  const existed = !!assets[editingBarcode];\n  const prev = assets[editingBarcode] || {};\n  const next = {\n    name, category: document.getElementById('f-category').value,\n    location: document.getElementById('f-location').value.trim(),\n    assignee: document.getElementById('f-assignee').value.trim(),\n    status: document.getElementById('f-status').value,\n    notes: document.getElementById('f-notes').value.trim(),\n    addedDate: prev.addedDate || new Date().toISOString(),\n    lastChecked: new Date().toISOString(),\n    history: prev.history || []\n  };\n  if(existed){\n    ['name','category','location','assignee','status','notes'].forEach(f=>{\n      if((prev[f]||'') !== (next[f]||'')) addHistory(editingBarcode, f, prev[f], next[f], 'manual');\n    });\n  }\n  assets[editingBarcode] = next;\n  await saveAssets();\n  modalBg.classList.remove('active');\n  toast(existed ? '\uc218\uc815\ub418\uc5c8\uc2b5\ub2c8\ub2e4.' : '\uc790\uc0b0\uc774 \ub4f1\ub85d\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');\n  renderAssetList();\n});\ndocument.getElementById('btn-delete-asset').addEventListener('click', async ()=>{\n  if(!confirm('\uc774 \uc790\uc0b0\uc744 \uc0ad\uc81c\ud560\uae4c\uc694? \ub418\ub3cc\ub9b4 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.')) return;\n  delete assets[editingBarcode];\n  await saveAssets();\n  modalBg.classList.remove('active');\n  toast('\uc0ad\uc81c\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');\n  renderAssetList();\n});\n\n/* ---------------- AI classify ---------------- */\ndocument.getElementById('btn-ai-classify').addEventListener('click', async ()=>{\n  const name = document.getElementById('f-name').value.trim();\n  if(!name){ toast('\uba3c\uc800 \uc790\uc0b0\uba85\uc744 \uc785\ub825\ud574\uc8fc\uc138\uc694.'); return; }\n  const btn = document.getElementById('btn-ai-classify');\n  const original = btn.textContent;\n  btn.innerHTML = '<span class=\"spin\"></span>'; btn.disabled = true;\n  try{\n    const existingCats = distinctCategories();\n    const prompt = `\ub108\ub294 \ud68c\uc0ac \uc790\uc0b0/\ucc28\ub7c9 \uad00\ub9ac \ubcf4\uc870\uc6d0\uc774\uc57c. \ub2e4\uc74c \uc790\uc0b0\uba85\uc744 \ubcf4\uace0 \uc801\uc808\ud55c \uce74\ud14c\uace0\ub9ac\ub97c \uc81c\uc548\ud574\uc918.\n\ud604\uc7ac \uc0ac\uc6a9 \uc911\uc778 \uce74\ud14c\uace0\ub9ac \uc608\uc2dc: ${existingCats.length ? existingCats.join(', ') : '(\uc544\uc9c1 \uc5c6\uc74c)'}\n\uac00\ub2a5\ud558\uba74 \uae30\uc874 \uce74\ud14c\uace0\ub9ac \uc911 \ud558\ub098\ub97c \uc7ac\uc0ac\uc6a9\ud558\uace0, \ub9c8\ub545\ud55c \uac83\uc774 \uc5c6\uc73c\uba74 \uc0c8\ub85c\uc6b4 \uc9e7\uc740 \uce74\ud14c\uace0\ub9ac\uba85\uc744 \ub9cc\ub4e4\uc5b4\uc918 (\uc608: \ucc28\ub7c9 \ucf54\ub4dc \uccb4\uacc4\ub77c\uba74 LMC, LPU \uac19\uc740 \ud615\uc2dd, \uc77c\ubc18 \ube44\ud488\uc774\uba74 \"\uc0ac\ubb34\uae30\uae30\" \uac19\uc740 \ud615\uc2dd).\n\uc790\uc0b0\uba85: \"${name}\"\n\ubc18\ub4dc\uc2dc JSON\ub9cc \uc751\ub2f5\ud574. \ud615\uc2dd: {\"category\":\"\uce74\ud14c\uace0\ub9ac\uba85\",\"suggested_notes\":\"\ud55c \ubb38\uc7a5 \uba54\ubaa8(\uc120\ud0dd, \uc5c6\uc73c\uba74 \ube48 \ubb38\uc790\uc5f4)\"}`;\n    const res = await apiFetch('/api/ai', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:300, messages:[{role:'user', content:prompt}] })\n    });\n    const data = await res.json();\n    const text = (data.content || []).filter(b=>b.type==='text').map(b=>b.text).join('');\n    const parsed = JSON.parse(text.replace(/```json|```/g,'').trim());\n    if(parsed.category) document.getElementById('f-category').value = parsed.category;\n    if(parsed.suggested_notes && !document.getElementById('f-notes').value) document.getElementById('f-notes').value = parsed.suggested_notes;\n    toast('AI\uac00 \uce74\ud14c\uace0\ub9ac\ub97c \uc81c\uc548\ud588\uc2b5\ub2c8\ub2e4.');\n  }catch(e){ toast('AI \ubd84\ub958\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4. \uc9c1\uc811 \uc785\ub825\ud574\uc8fc\uc138\uc694.'); }\n  finally{ btn.textContent = original; btn.disabled = false; }\n});\n\n/* ---------------- asset list ---------------- */\nlet activeCat = '\uc804\uccb4';\nlet activeLocation = '\uc804\uccb4';\n\nfunction distinctCategories(){\n  const set = new Set();\n  Object.values(assets).forEach(r=>{ if(r.category && r.category.trim()) set.add(r.category.trim()); });\n  return Array.from(set).sort((a,b)=> a.localeCompare(b, 'ko'));\n}\n\nfunction buildCategoryFilters(){\n  const el = document.getElementById('category-filters');\n  const cats = distinctCategories();\n  if(cats.length === 0){ el.innerHTML = '<span class=\"hint\" style=\"margin:0;\">\ub4f1\ub85d\ub41c \uce74\ud14c\uace0\ub9ac\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.</span>'; return; }\n  const options = ['\uc804\uccb4', ...cats];\n  el.innerHTML = options.map(c=>`<div class=\"chip ${c===activeCat?'active':''}\" data-cat=\"${escapeHtml(c)}\">${escapeHtml(c)}</div>`).join('');\n  el.querySelectorAll('.chip').forEach(chip=>{\n    chip.addEventListener('click', ()=>{ activeCat = chip.dataset.cat; buildCategoryFilters(); renderAssetList(); });\n  });\n  // also refresh the datalist used in the add/edit modal\n  const dl = document.getElementById('dl-category');\n  if(dl) dl.innerHTML = cats.map(c=>`<option value=\"${escapeHtml(c)}\">`).join('');\n}\n\nfunction distinctLocations(){\n  const set = new Set();\n  Object.values(assets).forEach(r=>{ if(r.location && r.location.trim()) set.add(r.location.trim()); });\n  return Array.from(set).sort((a,b)=> a.localeCompare(b, 'ko'));\n}\n\nfunction buildLocationFilters(){\n  const el = document.getElementById('location-filters');\n  const locs = distinctLocations();\n  if(locs.length === 0){ el.innerHTML = '<span class=\"hint\" style=\"margin:0;\">\ub4f1\ub85d\ub41c \uc704\uce58\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.</span>'; return; }\n  const options = ['\uc804\uccb4', ...locs, '(\uc704\uce58 \ubbf8\uc0c1)'];\n  el.innerHTML = options.map(loc=>`<div class=\"chip ${loc===activeLocation?'active':''}\" data-loc=\"${escapeHtml(loc)}\">${escapeHtml(loc)}</div>`).join('');\n  el.querySelectorAll('.chip').forEach(chip=>{\n    chip.addEventListener('click', ()=>{ activeLocation = chip.dataset.loc; buildLocationFilters(); renderAssetList(); });\n  });\n}\n\ndocument.getElementById('search-input').addEventListener('input', renderAssetList);\ndocument.getElementById('chk-group-location').addEventListener('change', renderAssetList);\n\nfunction assetItemHtml(code, r){\n  return `\n    <div class=\"asset-item\" data-code=\"${code}\">\n      <div class=\"strip\"></div>\n      <div class=\"body\">\n        <div class=\"top\"><span class=\"name\">${escapeHtml(r.name)}</span>${statusBadge(r.status)}</div>\n        <div class=\"meta\">${escapeHtml(r.category)} \u00b7 ${escapeHtml(r.location||'\uc704\uce58 \ubbf8\uc0c1')} \u00b7 ${escapeHtml(r.assignee||'\ub2f4\ub2f9\uc790 \ubbf8\uc0c1')}</div>\n        <div class=\"code mono\">${code}</div>\n        <div style=\"margin-top:6px;\">${checkBadge(daysSince(r.lastChecked))}</div>\n      </div>\n    </div>`;\n}\n\nfunction renderAssetList(){\n  buildCategoryFilters();\n  buildLocationFilters();\n  const q = document.getElementById('search-input').value.trim().toLowerCase();\n  const grouping = document.getElementById('chk-group-location').checked;\n  const list = document.getElementById('asset-list');\n  let entries = Object.entries(assets);\n\n  if(activeCat !== '\uc804\uccb4') entries = entries.filter(([,r])=> r.category === activeCat);\n  if(activeLocation !== '\uc804\uccb4'){\n    if(activeLocation === '(\uc704\uce58 \ubbf8\uc0c1)') entries = entries.filter(([,r])=> !r.location || !r.location.trim());\n    else entries = entries.filter(([,r])=> (r.location||'').trim() === activeLocation);\n  }\n  if(q){\n    entries = entries.filter(([code,r])=>\n      (r.name||'').toLowerCase().includes(q) || code.toLowerCase().includes(q) ||\n      (r.location||'').toLowerCase().includes(q) || (r.assignee||'').toLowerCase().includes(q));\n  }\n\n  if(entries.length === 0){\n    list.innerHTML = `<div class=\"empty\"><div class=\"big\">\ud83d\udce6</div>\uc870\uac74\uc5d0 \ub9de\ub294 \uc790\uc0b0\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.<br>\ud544\ud130\ub97c \ucd08\uae30\ud654\ud558\uac70\ub098 \uc0c8\ub85c \ub4f1\ub85d\ud574\ubcf4\uc138\uc694.</div>`;\n    return;\n  }\n\n  if(grouping){\n    const groups = {};\n    entries.forEach(([code,r])=>{\n      const key = (r.location && r.location.trim()) ? r.location.trim() : '\uc704\uce58 \ubbf8\uc0c1';\n      if(!groups[key]) groups[key] = [];\n      groups[key].push([code,r]);\n    });\n    const keys = Object.keys(groups).sort((a,b)=> a==='\uc704\uce58 \ubbf8\uc0c1' ? 1 : b==='\uc704\uce58 \ubbf8\uc0c1' ? -1 : a.localeCompare(b,'ko'));\n    list.innerHTML = keys.map(key=>{\n      const items = groups[key].sort((a,b)=> (daysSince(b[1].lastChecked) ?? 9999) - (daysSince(a[1].lastChecked) ?? 9999));\n      return `<div class=\"group-header\">${escapeHtml(key)}<div class=\"line\"></div><span class=\"cnt\">${items.length}</span></div>`\n        + items.map(([code,r])=> assetItemHtml(code,r)).join('');\n    }).join('');\n  }else{\n    entries.sort((a,b)=> (daysSince(b[1].lastChecked) ?? 9999) - (daysSince(a[1].lastChecked) ?? 9999));\n    list.innerHTML = entries.map(([code, r])=> assetItemHtml(code,r)).join('');\n  }\n\n  list.querySelectorAll('.asset-item').forEach(item=>{\n    item.addEventListener('click', ()=> openModal(item.dataset.code));\n  });\n}\n\n/* ---------------- bulk import (excel/csv) ---------------- */\nconst FIELD_DEFS = [\n  {key:'barcode', label:'\uc2dd\ubcc4\uc790(\ubc14\ucf54\ub4dc/\ucc28\ub7c9\ubc88\ud638) *\ud544\uc218', keywords:['\ubc14\ucf54\ub4dc','\ucc28\ub7c9\ubc88\ud638','\ucc28\ub7c9 \ubc88\ud638','plate','\ubc88\ud638\ud310','\uc2dd\ubcc4','\ucf54\ub4dc','id']},\n  {key:'name', label:'\uc790\uc0b0\uba85 *\ud544\uc218', keywords:['\uc790\uc0b0\uba85','\uc774\ub984','\ud488\uba85','name','\ucc28\uc885','\ubaa8\ub378']},\n  {key:'category', label:'\uce74\ud14c\uace0\ub9ac', keywords:['\uce74\ud14c\uace0\ub9ac','\ubd84\ub958','category','\uad6c\ubd84']},\n  {key:'location', label:'\uc704\uce58', keywords:['\uc704\uce58','\uc7a5\uc18c','location','\ubcf4\uad00']},\n  {key:'assignee', label:'\ub2f4\ub2f9\uc790/\uc0ac\uc6a9\uc790', keywords:['\ub2f4\ub2f9\uc790','\uc0ac\uc6a9\uc790','\uc6b4\uc804\uc790','assignee','user']},\n  {key:'status', label:'\uc0c1\ud0dc', keywords:['\uc0c1\ud0dc','status']},\n  {key:'notes', label:'\uba54\ubaa8', keywords:['\uba54\ubaa8','\ube44\uace0','notes','\uc124\uba85']},\n];\nlet parsedHeaders = [];\nlet parsedRows = [];\n\nfunction guessColumn(kw){\n  const idx = parsedHeaders.findIndex(h => kw.some(k => String(h).toLowerCase().includes(k.toLowerCase())));\n  return idx;\n}\nfunction normalizeStatus(v){\n  const s = String(v||'').trim();\n  if(!s) return 'ok';\n  if(/\ubd84\uc2e4|lost/i.test(s)) return 'lost';\n  if(/\ud3d0\uae30|\ub9e4\uac01|retired|\ud3d0\ucc28/i.test(s)) return 'retired';\n  if(/\uc810\uac80|\uc218\ub9ac|\uc815\ube44|check/i.test(s)) return 'check';\n  return 'ok';\n}\n\nconst dropZone = document.getElementById('drop-zone');\nconst fileInput = document.getElementById('file-input');\ndropZone.addEventListener('click', ()=> fileInput.click());\ndropZone.addEventListener('dragover', e=>{ e.preventDefault(); dropZone.classList.add('drag'); });\ndropZone.addEventListener('dragleave', ()=> dropZone.classList.remove('drag'));\ndropZone.addEventListener('drop', e=>{\n  e.preventDefault(); dropZone.classList.remove('drag');\n  if(e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);\n});\nfileInput.addEventListener('change', e=>{ if(e.target.files[0]) handleFile(e.target.files[0]); });\n\nfunction handleFile(file){\n  const reader = new FileReader();\n  reader.onload = (e)=>{\n    try{\n      const wb = XLSX.read(e.target.result, {type:'array'});\n      const ws = wb.Sheets[wb.SheetNames[0]];\n      const json = XLSX.utils.sheet_to_json(ws, {header:1, defval:''});\n      if(json.length < 2){ toast('\ud30c\uc77c\uc5d0 \ub370\uc774\ud130\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.'); return; }\n      parsedHeaders = json[0].map(h=>String(h).trim());\n      parsedRows = json.slice(1).filter(r=> r.some(c=> String(c).trim() !== ''));\n      renderMapping(file.name);\n    }catch(err){ toast('\ud30c\uc77c\uc744 \uc77d\ub294 \uc911 \uc624\ub958\uac00 \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4: ' + err.message); }\n  };\n  reader.readAsArrayBuffer(file);\n}\n\nfunction renderMapping(filename){\n  const box = document.getElementById('bulk-mapping');\n  const selectsHtml = FIELD_DEFS.map(f=>{\n    const guess = guessColumn(f.keywords);\n    const options = ['<option value=\"-1\">(\ub9e4\ud551 \uc548\ud568)</option>'].concat(\n      parsedHeaders.map((h,i)=>`<option value=\"${i}\" ${i===guess?'selected':''}>${escapeHtml(h)}</option>`)\n    ).join('');\n    return `<label>${f.label}</label><select data-field=\"${f.key}\">${options}</select>`;\n  }).join('');\n\n  box.innerHTML = `\n    <div class=\"card\">\n      <h2>\uc5f4 \ub9e4\ud551 \u2014 ${escapeHtml(filename)} (${parsedRows.length}\ud589 \ubc1c\uacac)</h2>\n      ${selectsHtml}\n      <div class=\"table-scroll\">\n        <table class=\"preview\" id=\"preview-table\"></table>\n      </div>\n      <button class=\"primary\" id=\"btn-run-import\" style=\"margin-top:14px;\">\uac00\uc838\uc624\uae30 \uc2e4\ud589 (${parsedRows.length}\uac74)</button>\n      <div id=\"import-summary\" style=\"margin-top:10px;\"></div>\n    </div>`;\n  box.querySelectorAll('select').forEach(s=> s.addEventListener('change', updatePreview));\n  updatePreview();\n}\n\nfunction currentMapping(){\n  const map = {};\n  document.querySelectorAll('#bulk-mapping select[data-field]').forEach(s=>{\n    map[s.dataset.field] = parseInt(s.value, 10);\n  });\n  return map;\n}\n\nfunction updatePreview(){\n  const map = currentMapping();\n  const table = document.getElementById('preview-table');\n  const cols = FIELD_DEFS.filter(f => map[f.key] >= 0);\n  let html = '<tr>' + cols.map(c=>`<th>${c.label.replace(' *\ud544\uc218','')}</th>`).join('') + '</tr>';\n  parsedRows.slice(0,5).forEach(row=>{\n    html += '<tr>' + cols.map(c=> `<td>${escapeHtml(row[map[c.key]] ?? '')}</td>`).join('') + '</tr>';\n  });\n  table.innerHTML = html;\n}\n\ndocument.getElementById('bulk-mapping').addEventListener('click', async (e)=>{\n  if(e.target.id !== 'btn-run-import') return;\n  const map = currentMapping();\n  if(map.barcode < 0 || map.name < 0){\n    toast('\uc2dd\ubcc4\uc790(\ubc14\ucf54\ub4dc/\ucc28\ub7c9\ubc88\ud638)\uc640 \uc790\uc0b0\uba85\uc740 \ubc18\ub4dc\uc2dc \ub9e4\ud551\ud574\uc57c \ud569\ub2c8\ub2e4.');\n    return;\n  }\n  const btn = e.target;\n  btn.disabled = true;\n  btn.innerHTML = '<span class=\"spin\"></span> \uac00\uc838\uc624\ub294 \uc911...';\n  let created = 0, updated = 0, skipped = 0;\n  parsedRows.forEach(row=>{\n    const barcode = String(row[map.barcode] ?? '').trim();\n    const name = String(row[map.name] ?? '').trim();\n    if(!barcode || !name){ skipped++; return; }\n    const existed = !!assets[barcode];\n    const prev = assets[barcode] || {};\n    assets[barcode] = {\n      name,\n      category: map.category >= 0 ? (String(row[map.category]||'').trim() || prev.category || '\uae30\ud0c0') : (prev.category || '\uae30\ud0c0'),\n      location: map.location >= 0 ? String(row[map.location]||'').trim() : (prev.location || ''),\n      assignee: map.assignee >= 0 ? String(row[map.assignee]||'').trim() : (prev.assignee || ''),\n      status: map.status >= 0 ? normalizeStatus(row[map.status]) : (prev.status || 'ok'),\n      notes: map.notes >= 0 ? String(row[map.notes]||'').trim() : (prev.notes || ''),\n      addedDate: prev.addedDate || new Date().toISOString(),\n      lastChecked: prev.lastChecked || new Date().toISOString(),\n      history: prev.history || []\n    };\n    if(existed){ addHistory(barcode, 'name', prev.name, name, 'import'); updated++; } else created++;\n  });\n  await saveAssets();\n  btn.disabled = false;\n  btn.textContent = `\uac00\uc838\uc624\uae30 \uc2e4\ud589 (${parsedRows.length}\uac74)`;\n  document.getElementById('import-summary').innerHTML =\n    `<p class=\"hint\" style=\"color:var(--ok);\">\uc644\ub8cc: \uc2e0\uaddc ${created}\uac74 \u00b7 \uc5c5\ub370\uc774\ud2b8 ${updated}\uac74 ${skipped?`\u00b7 \uac74\ub108\ub700 ${skipped}\uac74(\uc2dd\ubcc4\uc790/\uc774\ub984 \ub204\ub77d)`:''}</p>`;\n  toast('\uac00\uc838\uc624\uae30\uac00 \uc644\ub8cc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');\n  renderAssetList();\n});\n\n/* ---------------- dashboard ---------------- */\nfunction renderDashboard(){\n  const entries = Object.entries(assets);\n  const total = entries.length;\n  const needCheck = entries.filter(([,r])=> (daysSince(r.lastChecked) ?? 9999) > 90).length;\n  const lost = entries.filter(([,r])=> r.status === 'lost').length;\n  document.getElementById('stat-grid').innerHTML = `\n    <div class=\"stat\"><div class=\"num\">${total}</div><div class=\"lbl\">\uc804\uccb4 \uc790\uc0b0</div></div>\n    <div class=\"stat\"><div class=\"num\" style=\"color:${needCheck?'var(--warn)':'var(--text)'}\">${needCheck}</div><div class=\"lbl\">90\uc77c+ \ubbf8\ud655\uc778</div></div>\n    <div class=\"stat\"><div class=\"num\" style=\"color:${lost?'var(--danger)':'var(--text)'}\">${lost}</div><div class=\"lbl\">\ubd84\uc2e4 \ucc98\ub9ac</div></div>\n    <div class=\"stat\"><div class=\"num\">${distinctCategories().length}</div><div class=\"lbl\">\uce74\ud14c\uace0\ub9ac \uc218</div></div>`;\n  const byCat = {};\n  entries.forEach(([,r])=>{ byCat[r.category] = (byCat[r.category]||0) + 1; });\n  const maxCat = Math.max(1, ...Object.values(byCat));\n  document.getElementById('category-bars').innerHTML = Object.entries(byCat).length ?\n    Object.entries(byCat).sort((a,b)=>b[1]-a[1]).map(([cat,cnt])=>`\n      <div class=\"bar-row\"><div class=\"lbl\">${escapeHtml(cat)}</div><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:${(cnt/maxCat*100)}%\"></div></div><div class=\"cnt\">${cnt}</div></div>`).join('')\n    : '<p class=\"hint\">\ub370\uc774\ud130\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.</p>';\n  const byLoc = {};\n  entries.forEach(([,r])=>{\n    const key = (r.location && r.location.trim()) ? r.location.trim() : '\uc704\uce58 \ubbf8\uc0c1';\n    byLoc[key] = (byLoc[key]||0) + 1;\n  });\n  const maxLoc = Math.max(1, ...Object.values(byLoc));\n  document.getElementById('location-bars').innerHTML = Object.keys(byLoc).length ?\n    Object.entries(byLoc).sort((a,b)=>b[1]-a[1]).map(([loc,cnt])=>`\n      <div class=\"bar-row\"><div class=\"lbl\" title=\"${escapeHtml(loc)}\">${escapeHtml(loc)}</div><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:${(cnt/maxLoc*100)}%\"></div></div><div class=\"cnt\">${cnt}</div></div>`).join('')\n    : '<p class=\"hint\">\ub370\uc774\ud130\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.</p>';\n\n  const byStatus = {ok:0, check:0, lost:0, retired:0};\n  entries.forEach(([,r])=>{ byStatus[r.status] = (byStatus[r.status]||0) + 1; });\n  const statusLabels = {ok:'\uc815\uc0c1', check:'\uc810\uac80\ud544\uc694', lost:'\ubd84\uc2e4', retired:'\ud3d0\uae30'};\n  const maxSt = Math.max(1, ...Object.values(byStatus));\n  document.getElementById('status-bars').innerHTML = Object.entries(byStatus).map(([st,cnt])=>`\n      <div class=\"bar-row\"><div class=\"lbl\">${statusLabels[st]}</div><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:${(cnt/maxSt*100)}%\"></div></div><div class=\"cnt\">${cnt}</div></div>`).join('');\n}\ndocument.getElementById('btn-reset').addEventListener('click', async ()=>{\n  if(!confirm('\ubaa8\ub4e0 \uc790\uc0b0 \ub370\uc774\ud130\ub97c \uc0ad\uc81c\ud569\ub2c8\ub2e4. \uacc4\uc18d\ud560\uae4c\uc694?')) return;\n  assets = {}; await saveAssets(); toast('\ucd08\uae30\ud654\ub418\uc5c8\uc2b5\ub2c8\ub2e4.'); renderAssetList(); renderDashboard();\n});\n\n/* ---------------- AI chat + command ---------------- */\nfunction assetIndexForAI(){\n  return Object.entries(assets).map(([code,r])=>({\n    barcode:code, name:r.name, category:r.category, location:r.location,\n    assignee:r.assignee, status:r.status, daysSinceCheck: daysSince(r.lastChecked)\n  }));\n}\nfunction appendMsg(role, html){\n  const log = document.getElementById('chat-log');\n  const div = document.createElement('div');\n  div.className = 'msg ' + role;\n  div.innerHTML = html;\n  log.appendChild(div);\n  log.scrollTop = log.scrollHeight;\n  return div;\n}\n\nasync function askAI(userText){\n  appendMsg('user', escapeHtml(userText));\n  const pending = appendMsg('ai', '<span class=\"spin\"></span> \uc0dd\uac01 \uc911...');\n\n  try{\n    const index = JSON.stringify(assetIndexForAI());\n    const prompt = `\ub108\ub294 \ud68c\uc0ac \uc790\uc0b0/\ucc28\ub7c9 \uad00\ub9ac AI \ube44\uc11c\uc57c. \uc544\ub798\ub294 \ud604\uc7ac \ub4f1\ub85d\ub41c \uc790\uc0b0 \ubaa9\ub85d(\uc694\uc57d)\uc774\uc57c:\n${index}\n\n\uc0ac\uc6a9\uc790 \uc785\ub825: \"${userText}\"\n\n\uc774 \uc785\ub825\uc774 (a) \ub2e8\uc21c \uc9c8\ubb38/\uc870\ud68c\uc778\uc9c0 (b) \ud2b9\uc815 \uc790\uc0b0 \ud558\ub098\ub97c \uc9c0\ubaa9\ud574 \ud544\ub4dc\ub97c \ubcc0\uacbd\ud558\ub824\ub294 \uba85\ub839\uc778\uc9c0 (c) \uc870\uac74\uc5d0 \ub9de\ub294 \uc5ec\ub7ec \uc790\uc0b0\uc744 \ud55c\ubc88\uc5d0 \ubcc0\uacbd\ud558\ub824\ub294 \uba85\ub839\uc778\uc9c0 (d) \ubb34\uc5c7\uc744 \uc6d0\ud558\ub294\uc9c0 \ubd88\ubd84\uba85\ud55c\uc9c0 \ud310\ub2e8\ud574.\n\ubc18\ub4dc\uc2dc \uc544\ub798 JSON \ud615\uc2dd\uc73c\ub85c\ub9cc \uc751\ub2f5\ud558\uace0 \ub2e4\ub978 \ud14d\uc2a4\ud2b8\ub294 \uc808\ub300 \ud3ec\ud568\ud558\uc9c0 \ub9c8:\n\n\uc9c8\ubb38(a)\uc778 \uacbd\uc6b0: {\"intent\":\"query\",\"answer\":\"\uc2e4\uc81c \ub370\uc774\ud130\uc5d0 \uadfc\uac70\ud55c \ud55c\uad6d\uc5b4 \ub2f5\ubcc0(3~6\ubb38\uc7a5 \uc774\ub0b4)\"}\n\ub2e8\uc77c \ubcc0\uacbd(b)\uc778 \uacbd\uc6b0: {\"intent\":\"update\",\"target_query\":\"\uc790\uc0b0\uc744 \uc2dd\ubcc4\ud560 \uac80\uc0c9\uc5b4(\ucc28\ub7c9\ubc88\ud638/\uc774\ub984 \uc77c\ubd80 \ub4f1, \ucd5c\ub300\ud55c \uc9e7\uace0 \uc815\ud655\ud558\uac8c)\",\"field\":\"assignee|location|status|category|notes|name\",\"new_value\":\"\uc0c8 \uac12\"}\n\uc870\uac74\ubd80 \ub2e4\uc911 \ubcc0\uacbd(c)\uc778 \uacbd\uc6b0: {\"intent\":\"bulk_update\",\"target_query\":\"\ud544\ud130\ub9c1\uc5d0 \uc4f8 \uac80\uc0c9\uc5b4(\uc608: \uae30\uc874 \ub2f4\ub2f9\uc790 \uc774\ub984, \uc704\uce58\uba85 \ub4f1)\",\"field\":\"assignee|location|status|category|notes|name\",\"new_value\":\"\uc0c8 \uac12\"}\n\ubd88\ubd84\uba85(d)\uc778 \uacbd\uc6b0: {\"intent\":\"unclear\",\"answer\":\"\uc5b4\ub5a4 \uc815\ubcf4\uac00 \ub354 \ud544\uc694\ud55c\uc9c0 \ud55c\uad6d\uc5b4\ub85c \uc9e7\uac8c\"}\n\nstatus \uac12\uc744 \ubc14\uafb8\ub294 \uacbd\uc6b0 new_value\ub294 \ubc18\ub4dc\uc2dc ok, check, lost, retired \uc911 \ud558\ub098\uc5ec\uc57c \ud574(\uc815\uc0c1=ok, \uc810\uac80\ud544\uc694=check, \ubd84\uc2e4=lost, \ud3d0\uae30=retired).\n\ubaa9\ub85d\uc5d0 \uc5c6\ub294 \ub0b4\uc6a9\uc740 \ucd94\uce21\ud558\uc9c0 \ub9d0\uace0 \ubaa8\ub978\ub2e4\uace0 \ud574.`;\n    const res = await apiFetch('/api/ai', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:600, messages:[{role:'user', content:prompt}] })\n    });\n    const data = await res.json();\n    const text = (data.content || []).filter(b=>b.type==='text').map(b=>b.text).join('');\n    let parsed;\n    try{ parsed = JSON.parse(text.replace(/```json|```/g,'').trim()); }\n    catch(e){ parsed = {intent:'query', answer: text || '\uc751\ub2f5\uc744 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.'}; }\n\n    pending.remove();\n\n    if(parsed.intent === 'query' || parsed.intent === 'unclear'){\n      appendMsg('ai', escapeHtml(parsed.answer || '\ub2f5\ubcc0\uc744 \uc0dd\uc131\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.'));\n      return;\n    }\n    if(parsed.intent === 'update' || parsed.intent === 'bulk_update'){\n      handleUpdateIntent(parsed);\n      return;\n    }\n    appendMsg('ai', '\uc694\uccad\uc744 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\ub974\uac8c \ud45c\ud604\ud574 \uc8fc\uc138\uc694.');\n  }catch(e){\n    pending.remove();\n    appendMsg('ai', '\uc624\ub958\uac00 \ubc1c\uc0dd\ud588\uc2b5\ub2c8\ub2e4: ' + escapeHtml(e.message));\n  }\n}\n\nfunction findMatches(query){\n  const q = String(query||'').trim().toLowerCase();\n  if(!q) return [];\n  // exact barcode match first\n  const exact = Object.keys(assets).find(code => code.toLowerCase() === q);\n  if(exact) return [exact];\n  return Object.entries(assets).filter(([code, r])=>\n    code.toLowerCase().includes(q) ||\n    (r.name||'').toLowerCase().includes(q) ||\n    (r.assignee||'').toLowerCase().includes(q) ||\n    (r.location||'').toLowerCase().includes(q) ||\n    (r.category||'').toLowerCase().includes(q)\n  ).map(([code])=>code);\n}\n\nfunction handleUpdateIntent(parsed){\n  const matches = findMatches(parsed.target_query);\n  const field = parsed.field;\n  const newValue = field === 'status' ? normalizeStatus(parsed.new_value) : parsed.new_value;\n\n  if(!FIELD_LABEL[field]){\n    appendMsg('ai', `\uc54c \uc218 \uc5c6\ub294 \ud56d\ubaa9(${escapeHtml(field||'')})\uc744 \ubcc0\uacbd\ud558\ub824\uace0 \ud574\uc11c \ucc98\ub9ac\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.`);\n    return;\n  }\n  if(matches.length === 0){\n    appendMsg('ai', `\"${escapeHtml(parsed.target_query)}\"\uc5d0 \ud574\ub2f9\ud558\ub294 \uc790\uc0b0\uc744 \ucc3e\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ucc28\ub7c9\ubc88\ud638\ub098 \uc774\ub984\uc744 \uc815\ud655\ud788 \uc785\ub825\ud574 \ub2e4\uc2dc \uc2dc\ub3c4\ud574\uc8fc\uc138\uc694.`);\n    return;\n  }\n\n  const displayValue = (f,v) => f==='status' ? ({ok:'\uc815\uc0c1',check:'\uc810\uac80 \ud544\uc694',lost:'\ubd84\uc2e4',retired:'\ud3d0\uae30'}[v]||v) : v;\n  const rows = matches.slice(0,15).map(code=>{\n    const r = assets[code];\n    const from = r[field] || '(\uc5c6\uc74c)';\n    return `<div class=\"match-card\" data-code=\"${code}\">\n      <div><b>${escapeHtml(r.name)}</b> <span class=\"mono\" style=\"color:var(--muted); font-size:11px;\">${escapeHtml(code)}</span></div>\n      <div class=\"diff\"><span>${FIELD_LABEL[field]}: </span><span class=\"from\">${escapeHtml(displayValue(field, from))}</span> \u2192 <span class=\"to\">${escapeHtml(displayValue(field, newValue))}</span></div>\n    </div>`;\n  }).join('');\n\n  const moreNote = matches.length > 15 ? `<p class=\"hint\">\uadf8 \uc678 ${matches.length-15}\uac74 \ub354 \uc788\uc74c (\uac80\uc0c9\uc5b4\ub97c \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc785\ub825\ud574\uc8fc\uc138\uc694)</p>` : '';\n\n  const html = `\n    <div>${matches.length === 1 ? '\uc774 \uc790\uc0b0\uc744 \ucc3e\uc558\uc2b5\ub2c8\ub2e4:' : `${matches.length}\uac74\uc774 \uac80\uc0c9\ub418\uc5c8\uc2b5\ub2c8\ub2e4:`}</div>\n    ${rows}\n    ${moreNote}\n    <div class=\"match-actions\">\n      <button class=\"primary btn-apply-all\" style=\"flex:1;\">\uc804\uccb4 \uc801\uc6a9 (${Math.min(matches.length,15)}\uac74)</button>\n      <button class=\"secondary btn-cancel-apply\" style=\"flex:1;\">\ucde8\uc18c</button>\n    </div>`;\n  const div = appendMsg('ai', html);\n\n  div.querySelector('.btn-cancel-apply').addEventListener('click', ()=>{\n    div.querySelector('.match-actions').innerHTML = '<span class=\"hint\">\ucde8\uc18c\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</span>';\n  });\n  div.querySelector('.btn-apply-all').addEventListener('click', async ()=>{\n    div.querySelectorAll('.match-card').forEach(card=>{\n      const code = card.dataset.code;\n      const prevVal = assets[code][field] || '';\n      assets[code][field] = newValue;\n      assets[code].lastChecked = new Date().toISOString();\n      addHistory(code, field, prevVal, newValue, 'ai');\n    });\n    await saveAssets();\n    div.querySelector('.match-actions').innerHTML = `<span class=\"hint\" style=\"color:var(--ok);\">\u2713 ${Math.min(matches.length,15)}\uac74 \uc801\uc6a9 \uc644\ub8cc</span>`;\n    toast('AI \uba85\ub839\uc774 \uc801\uc6a9\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');\n    renderAssetList();\n  });\n}\n\ndocument.getElementById('btn-chat-send').addEventListener('click', ()=>{\n  const inp = document.getElementById('chat-input');\n  const v = inp.value.trim();\n  if(!v) return;\n  inp.value = '';\n  askAI(v);\n});\ndocument.getElementById('chat-input').addEventListener('keydown', e=>{\n  if(e.key === 'Enter'){ e.preventDefault(); document.getElementById('btn-chat-send').click(); }\n});\ndocument.querySelectorAll('.chip[data-prompt]').forEach(chip=>{\n  chip.addEventListener('click', ()=> askAI(chip.dataset.prompt));\n});\n\ndocument.getElementById('btn-export-excel').addEventListener('click', ()=>{\n  const statusLabels = {ok:'\uc815\uc0c1', check:'\uc810\uac80 \ud544\uc694', lost:'\ubd84\uc2e4', retired:'\ud3d0\uae30'};\n  const rows = Object.entries(assets).map(([code, r])=>({\n    '\ubc14\ucf54\ub4dc/\uc2dd\ubcc4\uc790': code,\n    '\uc790\uc0b0\uba85': r.name || '',\n    '\uce74\ud14c\uace0\ub9ac': r.category || '',\n    '\ubcf4\uad00\uc704\uce58': r.location || '',\n    '\ub2f4\ub2f9\uc790/\uc0ac\uc6a9\uc790': r.assignee || '',\n    '\uc0c1\ud0dc': statusLabels[r.status] || r.status || '',\n    '\ub9c8\uc9c0\ub9c9 \ud655\uc778\uc77c': r.lastChecked ? new Date(r.lastChecked).toLocaleString('ko-KR') : '',\n    '\uacbd\uacfc\uc77c\uc218': daysSince(r.lastChecked) ?? '',\n    '\ub4f1\ub85d\uc77c': r.addedDate ? new Date(r.addedDate).toLocaleString('ko-KR') : '',\n    '\uba54\ubaa8': r.notes || ''\n  }));\n  if(rows.length === 0){ toast('\ub0b4\ubcf4\ub0bc \ub370\uc774\ud130\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.'); return; }\n  try{\n    const ws = XLSX.utils.json_to_sheet(rows);\n    ws['!cols'] = [{wch:16},{wch:24},{wch:14},{wch:20},{wch:22},{wch:12},{wch:20},{wch:10},{wch:20},{wch:30}];\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, '\uc790\uc0b0\ud604\ud669');\n    const ts = new Date().toISOString().slice(0,10);\n    XLSX.writeFile(wb, `\uc790\uc0b0\ud604\ud669_${ts}.xlsx`);\n    toast('\uc5d1\uc140 \ud30c\uc77c\uc774 \ub2e4\uc6b4\ub85c\ub4dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');\n  }catch(e){ toast('\ub0b4\ubcf4\ub0b4\uae30 \uc2e4\ud328: ' + e.message); }\n});\n\ndocument.getElementById('btn-ai-report').addEventListener('click', async ()=>{\n  const box = document.getElementById('ai-report');\n  box.innerHTML = '<p class=\"hint\"><span class=\"spin\"></span> \ubd84\uc11d \uc911...</p>';\n  try{\n    const index = JSON.stringify(assetIndexForAI());\n    const prompt = `\ub108\ub294 \ud68c\uc0ac \uc790\uc0b0 \uad00\ub9ac AI \ube44\uc11c\uc57c. \uc544\ub798 \uc790\uc0b0 \ubaa9\ub85d(JSON)\uc744 \ubd84\uc11d\ud574\uc11c \uc774\uc0c1 \uc9d5\ud6c4\ub97c \ucc3e\uc544\uc918: 90\uc77c \uc774\uc0c1 \ubbf8\ud655\uc778, \uc0c1\ud0dc\uac00 \"lost\"\uc774\uac70\ub098 \"check\"\uc778 \uc790\uc0b0, \uc704\uce58/\ub2f4\ub2f9\uc790 \uc815\ubcf4\uac00 \ube44\uc5b4\uc788\ub294 \uc790\uc0b0 \ub4f1.\n${index}\n\ud55c\uad6d\uc5b4\ub85c \uc9e7\uc740 \ubd88\ub9bf \ub9ac\uc2a4\ud2b8\ub85c, \uc2e4\uc81c \ub370\uc774\ud130\uc5d0 \uadfc\uac70\ud574\uc11c\ub9cc \ub2f5\ud574. \ubb38\uc81c \uc5c6\uc73c\uba74 \"\ud2b9\uc774\uc0ac\ud56d \uc5c6\uc74c\"\uc774\ub77c\uace0 \ub2f5\ud574.`;\n    const res = await apiFetch('/api/ai', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:800, messages:[{role:'user', content:prompt}] })\n    });\n    const data = await res.json();\n    const text = (data.content || []).filter(b=>b.type==='text').map(b=>b.text).join('') || '\ubd84\uc11d \uacb0\uacfc\ub97c \ubc1b\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.';\n    box.innerHTML = `<div class=\"msg ai\" style=\"max-width:100%;\">${escapeHtml(text)}</div>`;\n  }catch(e){ box.innerHTML = `<p class=\"hint\">\ubd84\uc11d \uc624\ub958: ${escapeHtml(e.message)}</p>`; }\n});\n\n/* ---------------- init ---------------- */\n(async function init(){\n  await loadAssets();\n  renderAssetList();\n  renderDashboard();\n})();\n</script>\n</body>\n</html>\n";

function checkAuth(request, env) {
  const token = request.headers.get("x-app-token") || "";
  return Boolean(env.APP_ACCESS_TOKEN) && token === env.APP_ACCESS_TOKEN;
}

function unauthorized() {
  return new Response(JSON.stringify({error: "인증 실패 (접속 코드를 확인하세요)"}), {
    status: 401,
    headers: {"Content-Type": "application/json", ...CORS_HEADERS},
  });
}

function jsonResponse(data, status = 200) {
  return new Response(typeof data === "string" ? data : JSON.stringify(data), {
    status,
    headers: {"Content-Type": "application/json", ...CORS_HEADERS},
  });
}

async function handleAssetsGet(env) {
  const value = await env.ASSETS_KV.get(KV_KEY);
  return jsonResponse(value || "{}");
}

async function handleAssetsPost(request, env) {
  try {
    const body = await request.text();
    JSON.parse(body);
    await env.ASSETS_KV.put(KV_KEY, body);
    return jsonResponse({ok: true});
  } catch (err) {
    return jsonResponse({error: err.message}, 400);
  }
}

async function handleAI(request, env) {
  try {
    const body = await request.text();
    const upstream = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
      },
      body,
    });
    const data = await upstream.text();
    return new Response(data, {
      status: upstream.status,
      headers: {"Content-Type": "application/json", ...CORS_HEADERS},
    });
  } catch (err) {
    return jsonResponse({error: err.message}, 500);
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS" && url.pathname.startsWith("/api/")) {
      return new Response(null, {status: 204, headers: CORS_HEADERS});
    }

    if (url.pathname === "/api/assets") {
      if (!checkAuth(request, env)) return unauthorized();
      if (request.method === "GET") return handleAssetsGet(env);
      if (request.method === "POST") return handleAssetsPost(request, env);
      return jsonResponse({error: "Method Not Allowed"}, 405);
    }

    if (url.pathname === "/api/ai") {
      if (!checkAuth(request, env)) return unauthorized();
      if (request.method === "POST") return handleAI(request, env);
      return jsonResponse({error: "Method Not Allowed"}, 405);
    }

    // 그 외 모든 요청은 내장된 앱 화면(HTML)을 그대로 응답
    return new Response(HTML_CONTENT, {
      headers: {"Content-Type": "text/html; charset=utf-8"},
    });
  },
};
